version.transform:
$query({
  "statement":"query($where:DataModelVersionWhereInput){ dataModelVersion(first:1, orderBy: {field: updatedAt, direction: desc}, where: $where){edges{node{ id modelDefinition}}}}",
  "variables": {
    "where": {
      "deployed": {
        "_eq":true
      },
      "dataModelId": {
        "_eq":dataModelId
      }
    }
  }
}).dataModelVersion.edges.node.modelDefinition.fields.name
